Here is the commit message:
ACPICA: Fix NULL pointer dereference in
 acpi_ev_address_space_dispatch()

Cover a missed execution path with a new check.

Fixes: 0acf24ad7e10 ("ACPICA: Add support for PCC Opregion special context data")
Link: https://github.com/acpica/acpica/commit/f421dd9dd897
Signed-off-by: Alexey Simakov <bigalex934@gmail.com>
Signed-off-by: Rafael J. Wysocki <rafael.j.wysocki@intel.com>
Link: https://patch.msgid.link/3030574.e9J7NaK4W3@rafael.j.wysocki

Here is the root cause:
The function `acpi_ev_address_space_dispatch()` in `evregion.c` does not check if `field_obj` is NULL before entering the code path that handles `ACPI_ADR_SPACE_PLATFORM_COMM` (PCC address space). This missing NULL check can lead to a NULL pointer dereference when the function is invoked with a NULL `field_obj`, a scenario that was not covered by the original fix for PCC support (commit 0acf24ad7e10).

Here is the patch:

 acpi_status
 acpi_ev_address_space_dispatch(union acpi_operand_object *region_obj,
 			       union acpi_operand_object *field_obj,
 			       u32 function,
 			       u32 region_offset, u32 bit_width, u64 *value)
 {
 	acpi_status status;
 	acpi_adr_space_handler handler;
 	acpi_adr_space_setup region_setup;
 	union acpi_operand_object *handler_desc;
 	union acpi_operand_object *region_obj2;
 	void *region_context = NULL;
 	struct acpi_connection_info *context;
 	acpi_mutex context_mutex;
 	u8 context_locked;
 	acpi_physical_address address;

 	ACPI_FUNCTION_TRACE(ev_address_space_dispatch);

 	region_obj2 = acpi_ns_get_secondary_object(region_obj);
 	if (!region_obj2) {
 		return_ACPI_STATUS(AE_NOT_EXIST);
 	}

 	/* Ensure that there is a handler associated with this region */

 	handler_desc = region_obj->region.handler;
 	if (!handler_desc) {
 		ACPI_ERROR((AE_INFO,
 			    "No handler for Region [%4.4s] (%p) [%s]",
 			    acpi_ut_get_node_name(region_obj->region.node),
 			    region_obj,
 			    acpi_ut_get_region_name(region_obj->region.
 						    space_id)));

 		return_ACPI_STATUS(AE_NOT_EXIST);
 	}

 	context = handler_desc->address_space.context;
 	context_mutex = handler_desc->address_space.context_mutex;
 	context_locked = FALSE;

 	/*
 	 * It may be the case that the region has never been initialized.
 	 * Some types of regions require special init code
 	 */
 	if (!(region_obj->region.flags & AOPOBJ_SETUP_COMPLETE)) {

 		/* This region has not been initialized yet, do it */

 		region_setup = handler_desc->address_space.setup;
 		if (!region_setup) {

 			/* No initialization routine, exit with error */

 			ACPI_ERROR((AE_INFO,
 				    "No init routine for region(%p) [%s]",
 				    region_obj,
 				    acpi_ut_get_region_name(region_obj->region.
 							    space_id)));
 			return_ACPI_STATUS(AE_NOT_EXIST);
 		}

-		if (region_obj->region.space_id == ACPI_ADR_SPACE_PLATFORM_COMM) {
+		if (field_obj
+		    && region_obj->region.space_id ==
+		    ACPI_ADR_SPACE_PLATFORM_COMM) {
 			struct acpi_pcc_info *ctx =
 			    handler_desc->address_space.context;

 			ctx->internal_buffer =
 			    field_obj->field.internal_pcc_buffer;
 			ctx->length = (u16)region_obj->region.length;
 			ctx->subspace_id = (u8)region_obj->region.address;
 		}

 		if (region_obj->region.space_id ==
 		    ACPI_ADR_SPACE_FIXED_HARDWARE) {
 			struct acpi_ffh_info *ctx =
 			    handler_desc->address_space.context;

 			ctx->length = region_obj->region.length;
 			ctx->offset = region_obj->region.address;
 		}

 		/*
 		 * We must exit the interpreter because the region setup will
 		 * potentially execute control methods (for example, the _REG method
 		 * for this region)
 		 */
 		acpi_ex_exit_interpreter();

 		status = region_setup(region_obj, ACPI_REGION_ACTIVATE,
 				      context, &region_context);

 		/* Re-enter the interpreter */

 		acpi_ex_enter_interpreter();

 		/* Check for failure of the Region Setup */

 		if (ACPI_FAILURE(status)) {
 			ACPI_EXCEPTION((AE_INFO, status,
 					"During region initialization: [%s]",
 					acpi_ut_get_region_name(region_obj->
 								region.
 								space_id)));
 			return_ACPI_STATUS(status);
 		}

 		/* Region initialization may have been completed by region_setup */

 		if (!(region_obj->region.flags & AOPOBJ_SETUP_COMPLETE)) {
 			region_obj->region.flags |= AOPOBJ_SETUP_COMPLETE;

 			/*
 			 * Save the returned context for use in all accesses to
 			 * the handler for this particular region
 			 */
 			if (!(region_obj2->extra.region_context)) {
 				region_obj2->extra.region_context =
 				    region_context;
 			}
 		}
 	}

 	/* We have everything we need, we can invoke the address space handler */

 	handler = handler_desc->address_space.handler;
 	address = (region_obj->region.address + region_offset);

 	ACPI_DEBUG_PRINT((ACPI_DB_OPREGION,
 			  "Handler %p (@%p) Address %8.8X%8.8X [%s]\n",
 			  &region_obj->region.handler->address_space, handler,
 			  ACPI_FORMAT_UINT64(address),
 			  acpi_ut_get_region_name(region_obj->region.
 						  space_id)));

 	if (!(handler_desc->address_space.handler_flags &
 	      ACPI_ADDR_HANDLER_DEFAULT_INSTALLED)) {
 		/*
 		 * For handlers other than the default (supplied) handlers, we must
 		 * exit the interpreter because the handler *might* block -- we don't
 		 * know what it will do, so we can't hold the lock on the interpreter.
 		 */
 		acpi_ex_exit_interpreter();
 	}

 	/*
 	 * Special handling for generic_serial_bus and general_purpose_io:
 	 * There are three extra parameters that must be passed to the
 	 * handler via the context:
 	 *   1) Connection buffer, a resource template from Connection() op
 	 *   2) Length of the above buffer
 	 *   3) Actual access length from the access_as() op
 	 *
 	 * Since we pass these extra parameters via the context, which is
 	 * shared between threads, we must lock the context to avoid these
 	 * parameters being changed from another thread before the handler
 	 * has completed running.
 	 *
 	 * In addition, for general_purpose_io, the Address and bit_width fields
 	 * are defined as follows:
 	 *   1) Address is the pin number index of the field (bit offset from
 	 *      the previous Connection)
 	 *   2) bit_width is the actual bit length of the field (number of pins)
 	 */
 	if ((region_obj->region.space_id == ACPI_ADR_SPACE_GSBUS ||
 	     region_obj->region.space_id == ACPI_ADR_SPACE_GPIO) &&
 	    context && field_obj) {

 		status =
 		    acpi_os_acquire_mutex(context_mutex, ACPI_WAIT_FOREVER);
 		if (ACPI_FAILURE(status)) {
 			goto re_enter_interpreter;
 		}

 		context_locked = TRUE;

 		/* Get the Connection (resource_template) buffer */

 		context->connection = field_obj->field.resource_buffer;
 		context->length = field_obj->field.resource_length;
 		context->access_length = field_obj->field.access_length;

 		if (region_obj->region.space_id == ACPI_ADR_SPACE_GPIO) {
 			address = field_obj->field.pin_number_index;
 			bit_width = field_obj->field.bit_length;
 		}
 	}

 	/* Call the handler */

 	status = handler(function, address, bit_width, value, context,
 			 region_obj2->extra.region_context);

 	if (context_locked) {
 		acpi_os_release_mutex(context_mutex);
 	}

 	if (ACPI_FAILURE(status)) {
 		ACPI_EXCEPTION((AE_INFO, status, "Returned by Handler for [%s]",
 				acpi_ut_get_region_name(region_obj->region.
 							space_id)));

 		/*
 		 * Special case for an EC timeout. These are seen so frequently
 		 * that an additional error message is helpful
 		 */
 		if ((region_obj->region.space_id == ACPI_ADR_SPACE_EC) &&
 		    (status == AE_TIME)) {
 			ACPI_ERROR((AE_INFO,
 				    "Timeout from EC hardware or EC device driver"));
 		}
 	}

 re_enter_interpreter:
 	if (!(handler_desc->address_space.handler_flags &
 	      ACPI_ADDR_HANDLER_DEFAULT_INSTALLED)) {
 		/*
 		 * We just returned from a non-default handler, we must re-enter the
 		 * interpreter
 		 */
 		acpi_ex_enter_interpreter();
 	}

 	return_ACPI_STATUS(status);
 }



